+pub fn offset(run: &[Point2], s: f64, z: f64, v: Voice) -> Result<Vec<Point2>, GenError> {
+    let n = run.len();
+    if n < 2 || run.windows(2).any(|w| dist(w[0], w[1]) <= 0.0) {
+        return Err(v.invalid("the open run has no length - there is nothing to cut along".into()));
