+                v,
+                format!(
+                    "a corner of the open run near X{:.3} Y{:.3} is tighter than the {} can follow on its {} side - the minimum inside radius is the kerf offset ({:.4} mm)",
+                    q.x,
+                    q.y,
+                    v.tool,
